/**
 * CLIP EDITION 2026-09-25 の注釈 (全文)。
 *
 * newspaper.ts の SentenceGloss を短く書くための形:
 *   g(en, ja, why, chunks, picks)
 *   chunks = [英語の切れ端, 日本語] の配列。英語を順につなぐと en に戻る
 *   picks  = [表現, 日本語, 'w' | 'p'] の配列。w = Words に登録 / p = Phrases に登録
 * 検査は scripts/verify-newspaper-clip.mjs (全文に注釈があるか、chunks が元に戻るか)。
 */
import type { SentenceGloss } from './newspaper';
import { CLIP_0925_VS_GLOSSES } from './newspaper-clip-glosses-town';

type C = [string, string];
type P = [string, string, 'w' | 'p'];

function g(en: string, ja: string, why: string, chunks: C[], picks: P[]): SentenceGloss {
    return {
        en, ja, why,
        chunks: chunks.map(([e, j]) => ({ en: e, ja: j })),
        picks: picks.map(([e, j, k]) => ({ en: e, ja: j, kind: k === 'w' ? 'word' : 'phrase' })),
    };
}

